local __ezs_original_env = (getfenv and getfenv(0)) or _G

-- NOTE: ห้าม clone ด้วย pairs() — executor หลายตัว (Xeno/Delta) ห่อ string/bit32
-- เป็น special object ที่ pairs() ได้ไม่ครบทุก field → clone ขาด field →
-- "attempt to call a nil value" ใน VM ของ obfuscator ที่ใช้ string.char ฯลฯ
-- ใช้ proxy metatable แทน: field ใดไม่ถูก override จะไปเรียกตัวจริงผ่าน __index เสมอ
local __ezs_string_proxy
do
  local overrides = {}
  if type(string) ~= "table" or type(string.pack) ~= "function" then
    overrides.pack = function(fmt, n)
      if fmt ~= ">I4" and fmt ~= "I4" then
        error("unsupported string.pack format: " .. tostring(fmt), 2)
      end
      n = tonumber(n) or 0
      local b4 = n % 256; n = math.floor(n / 256)
      local b3 = n % 256; n = math.floor(n / 256)
      local b2 = n % 256; n = math.floor(n / 256)
      local b1 = n % 256
      local sc = (type(string) == "table" and string.char) or __ezs_original_env.string.char
      if fmt == "I4" then
        return sc(b4, b3, b2, b1)
      end
      return sc(b1, b2, b3, b4)
    end
  end
  if next(overrides) then
    __ezs_string_proxy = setmetatable(overrides, { __index = string })
  end
end

local __ezs_bit32_proxy
do
  local overrides = {}
  if type(bit32) ~= "table" or type(bit32.band) ~= "function" then
    overrides.band = function(a, b)
      a, b = tonumber(a) or 0, tonumber(b) or 0
      local res, bit = 0, 1
      while a > 0 or b > 0 do
        local aa, bb = a % 2, b % 2
        if aa == 1 and bb == 1 then res = res + bit end
        a = math.floor(a / 2); b = math.floor(b / 2); bit = bit * 2
      end
      return res
    end
  end
  if type(bit32) ~= "table" or type(bit32.bxor) ~= "function" then
    overrides.bxor = function(a, b)
      a, b = tonumber(a) or 0, tonumber(b) or 0
      local res, bit = 0, 1
      while a > 0 or b > 0 do
        local aa, bb = a % 2, b % 2
        if aa ~= bb then res = res + bit end
        a = math.floor(a / 2); b = math.floor(b / 2); bit = bit * 2
      end
      return res
    end
  end
  if next(overrides) then
    __ezs_bit32_proxy = setmetatable(overrides, { __index = bit32 })
  end
end

