      local info = game:GetService("MarketplaceService"):GetProductInfo(game.PlaceId)
      if info and info.Name then gname = tostring(info.Name) end
    end)
    if gname == "" then gname = "Place " .. pid end
    local function enc(s) return HS:UrlEncode(tostring(s or "")) end
